/**
 * @brief Test the encoding of the unique EIP-4527 test vector provided by Keystone team in ur-registry-eth package
 * Source: 
 * - https://eips.ethereum.org/EIPS/eip-4527
 * - https://github.com/KeystoneHQ/keystone-sdk-base/blob/7f62721aaf7cdf25cc04f70f67da3a8658f2fcbe/packages/ur-registry-eth/__tests__/EthSignature.test.ts
 * CDDL:
 * {
 *    1: 37(h'9b1deb4d3b7d4bad9bdd2b0d7b3dcb6d'), 
 *    2: h'd4f0a7bcd95bba1fbb1051885054730e3f47064288575aacc102fbbf6a9a14daa066991e360d3e3406c20c00a40973eff37c7d641e5b351ec4a99bfe86f335f713',
 *    3: "keystone" 
 * }
 * 
 */
void TestUrSignatures::EncodeSignatureKeystoneTestCase()
{
    // eth-signature
    std::string request_id = "9b1deb4d-3b7d-4bad-9bdd-2b0d7b3dcb6d";
    auto rlpSignatureData = fromHex("d4f0a7bcd95bba1fbb1051885054730e3f47064288575aacc102fbbf6a9a14daa066991e360d3e3406c20c00a40973eff37c7d641e5b351ec4a99bfe86f335f713");
    EthSignature ethsignature(Uuid(request_id), rlpSignatureData, "keystone");

    auto expectedBytes = fromHex("A301D825509B1DEB4D3B7D4BAD9BDD2B0D7B3DCB6D025841D4F0A7BCD95BBA1FBB1051885054730E3F47064288575AACC102FBBF6A9A14DAA066991E360D3E3406C20C00A40973EFF37C7D641E5B351EC4A99BFE86F335F71303686B657973746F6E65");
    auto expectedUR = "ur:eth-signature/otadtpdagdndcawmgtfrkigrpmndutdnbtkgfssbjnaohdfptywtosrftahprdctrkbegylogdghjkbafhflamfwlohghtpsseaozorsimnybbtnnbiynlckenbtfmeeamsabnaeoxasjkwswfkekiieckhpecckssptndzelnwfecylbwaxisjeihkkjkjyjljtihdwlkamiy";

    ValidateCborResults(ethsignature, expectedBytes);
    ValidateUrEncoding(ethsignature, expectedUR);

    // sign-response
    SignResponse signresponse(Uuid(request_id), rlpSignatureData, "keystone");
    expectedUR = "ur:sign-response/otadtpdagdndcawmgtfrkigrpmndutdnbtkgfssbjnaohdfptywtosrftahprdctrkbegylogdghjkbafhflamfwlohghtpsseaozorsimnybbtnnbiynlckenbtfmeeamsabnaeoxasjkwswfkekiieckhpecckssptndzelnwfecylbwaxisjeihkkjkjyjljtihdwlkamiy";

    ValidateCborResults(signresponse, expectedBytes);
    ValidateUrEncoding(signresponse, expectedUR);
}

/**
 * @brief Test the encoding of this CDDL example
 * {
 *    1: 37(h'FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'), 
 *    2: h'e0a03ffb67afc6c36aab750a237e75b0c57e89a72d9ed5ddda17707c7b36e7ae1507e013c952b1a9e74d19578dc5cca0ebb14e2c4057417e76664b087c42208b014985'
 * }
 * 
 */
void TestUrSignatures::EncodeSignatureWithoutOriginAndSignatureAbove65B()
{
    // eth-signature
    EthSignature ethsignature;
    ur::ByteVector uuid(UUID_SIZE, 0XFF);
    auto rlpSignatureData = fromHex("e0a03ffb67afc6c36aab750a237e75b0c57e89a72d9ed5ddda17707c7b36e7ae1507e013c952b1a9e74d19578dc5cca0ebb14e2c4057417e76664b087c42208b014985");
    ethsignature.setRequestID(Uuid(uuid));
    ethsignature.setSignature(rlpSignatureData);

    auto expectedBytes = fromHex("A201D82550FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF025843E0A03FFB67AFC6C36AAB750A237E75B0C57E89A72D9ED5DDDA17707C7B36E7AE1507E013C952B1A9E74D19578DC5CCA0EBB14E2C4057417E76664B087C42208B014985");
    auto expectedUR = std::string("ur:eth-signature/oeadtpdagdzmzmzmzmzmzmzmzmzmzmzmzmzmzmzmzmaohdfxvtnbfhzoiopeswsrimpykpbkcnkbkppfskkbldosdpnntluttnchjokekgenvdplbzatvtbwsogmpaptvdgtcfhglgsksfnbwmpagldwfzhgfpkbkoiygraykefwcxluadgalpglrdplie");

    ValidateCborResults(ethsignature, expectedBytes);
    ValidateUrEncoding(ethsignature, expectedUR);

    // sign-response
    SignResponse signresponse;
    signresponse.setRequestID(Uuid(uuid));
    signresponse.setSignature(rlpSignatureData);
    expectedUR = "ur:sign-response/oeadtpdagdzmzmzmzmzmzmzmzmzmzmzmzmzmzmzmzmaohdfxvtnbfhzoiopeswsrimpykpbkcnkbkppfskkbldosdpnntluttnchjokekgenvdplbzatvtbwsogmpaptvdgtcfhglgsksfnbwmpagldwfzhgfpkbkoiygraykefwcxluadgalpglrdplie";

    ValidateCborResults(signresponse, expectedBytes);
    ValidateUrEncoding(signresponse, expectedUR);
}

void TestUrSignatures::EncodeSignatureWithInvalidRequestId()
{
    // eth-signature
    EthSignature ethsignature;
    ur::ByteVector invalid_uuid(UUID_SIZE+4, 0XFF); // Initialize with incorrect uuid size
    auto rlpSignatureData = fromHex("d4f0a7bcd95bba1fbb1051885054730e3f47064288575aacc102fbbf6a9a14daa066991e360d3e3406c20c00a40973eff37c7d641e5b351ec4a99bfe86f335f713");
    ethsignature.setRequestID(Uuid(invalid_uuid));
    ethsignature.setSignature(rlpSignatureData);

    ValidateUrEncodingException(ethsignature, CborErrorImproperValue);

    // sign-response
    SignResponse signresponse;
    signresponse.setRequestID(Uuid(invalid_uuid));
    signresponse.setSignature(rlpSignatureData);

    ValidateUrEncodingException(signresponse, CborErrorImproperValue);
}

/**
 * @brief Test the encoding of this CDDL example
 * {
 *    1: 37(h'11111111111111111111111111111111'), 
 *    2: h'123456789A'
 * }
 * 
 */
void TestUrSignatures::EncodeSignatureWithSizeBelow65B()
{
    // eth-signature
    ur::ByteVector uuid(UUID_SIZE, 0x11); 
    auto rlpSignatureData = fromHex("123456789A"); // Invalid signature size
    EthSignature ethsignature(Uuid(uuid), rlpSignatureData);

    ValidateUrEncodingException(ethsignature, CborErrorImproperValue);

    // sign-response
    SignResponse signresponse(Uuid(uuid), rlpSignatureData);

    auto expectedBytes = fromHex("A201D82550111111111111111111111111111111110245123456789A");
    auto expectedUR = "ur:sign-response/oeadtpdagdbybybybybybybybybybybybybybybybyaofebgeehfksnybyjnrlba";

    ValidateCborResults(signresponse, expectedBytes);
    ValidateUrEncoding(signresponse, expectedUR);
}

/**
 * @brief Test the encoding of this CDDL example
 * {
 *    2: h'd4f0a7bcd95bba1fbb1051885054730e3f47064288575aacc102fbbf6a9a14daa066991e360d3e3406c20c00a40973eff37c7d641e5b351ec4a99bfe86f335f713',
 *    3: "Ngrave"
 * }
 * 
 * eth-signature has request id as mandatory field
 * {
 *    1: 37(h'00000000000000000000000000000000'),
 *    2: h'd4f0a7bcd95bba1fbb1051885054730e3f47064288575aacc102fbbf6a9a14daa066991e360d3e3406c20c00a40973eff37c7d641e5b351ec4a99bfe86f335f713',
 *    3: "Ngrave"
 * }
 */
void TestUrSignatures::EncodeSignatureWithoutRequestId()
{
    // eth-signature
    auto rlpSignatureData = fromHex("d4f0a7bcd95bba1fbb1051885054730e3f47064288575aacc102fbbf6a9a14daa066991e360d3e3406c20c00a40973eff37c7d641e5b351ec4a99bfe86f335f713"); // Invalid signature size
    EthSignature ethsignature;
    ethsignature.setSignature(rlpSignatureData);
    ethsignature.setOrigin("Ngrave");

    auto expectedBytes = fromHex("A301D8255000000000000000000000000000000000025841D4F0A7BCD95BBA1FBB1051885054730E3F47064288575AACC102FBBF6A9A14DAA066991E360D3E3406C20C00A40973EFF37C7D641E5B351EC4A99BFE86F335F71303664E6772617665");
    auto expectedUR = "ur:eth-signature/otadtpdagdaeaeaeaeaeaeaeaeaeaeaeaeaeaeaeaeaohdfptywtosrftahprdctrkbegylogdghjkbafhflamfwlohghtpsseaozorsimnybbtnnbiynlckenbtfmeeamsabnaeoxasjkwswfkekiieckhpecckssptndzelnwfecylbwaxiygliojphskoihcavthfvd";

    ValidateCborResults(ethsignature, expectedBytes);
    ValidateUrEncoding(ethsignature, expectedUR);

    // sign-response
    SignResponse signresponse;
    signresponse.setSignature(rlpSignatureData);
    signresponse.setOrigin("Ngrave");

    expectedBytes = fromHex("A2025841D4F0A7BCD95BBA1FBB1051885054730E3F47064288575AACC102FBBF6A9A14DAA066991E360D3E3406C20C00A40973EFF37C7D641E5B351EC4A99BFE86F335F71303664E6772617665");
    expectedUR = "ur:sign-response/oeaohdfptywtosrftahprdctrkbegylogdghjkbafhflamfwlohghtpsseaozorsimnybbtnnbiynlckenbtfmeeamsabnaeoxasjkwswfkekiieckhpecckssptndzelnwfecylbwaxiygliojphskoihmhchpaln";

    ValidateCborResults(signresponse, expectedBytes);
    ValidateUrEncoding(signresponse, expectedUR);
    
    // sign-response with public-key
    signresponse.setPublickey(fromHex("D65D1112F26BA920A73A6BEF5C2071912C1D33E95670D6BE36C888CAF7E52A4C"));

    expectedBytes = fromHex("A3025841D4F0A7BCD95BBA1FBB1051885054730E3F47064288575AACC102FBBF6A9A14DAA066991E360D3E3406C20C00A40973EFF37C7D641E5B351EC4A99BFE86F335F71303664E6772617665045820D65D1112F26BA920A73A6BEF5C2071912C1D33E95670D6BE36C888CAF7E52A4C");
    expectedUR = "ur:sign-response/otaohdfptywtosrftahprdctrkbegylogdghjkbafhflamfwlohghtpsseaozorsimnybbtnnbiynlckenbtfmeeamsabnaeoxasjkwswfkekiieckhpecckssptndzelnwfecylbwaxiygliojphskoihaahdcxtbhlbybgwzjeptcxosftjewshhcxjsmedwcaeowlhfjotbrnensplosgylvwdrgssgnysnhn";

    ValidateCborResults(signresponse, expectedBytes);
    ValidateUrEncoding(signresponse, expectedUR);
}

void TestUrSignatures::EncodeBatchSignResponse()
{
    BatchSignResponse batchSignResponse;
    
    
    // Empty sign-request vector
    CPPUNIT_ASSERT_THROW(batchSignResponse.toCbor(), CborException);
    
    SignResponse signresponse0;
    auto psbtSignatureData = fromHex("");
    signresponse0.setSignature(psbtSignatureData);
    signresponse0.setOrigin("NGRAVE");

    SignResponse signresponse1;
    psbtSignatureData = fromHex("");
    signresponse1.setRequestID(Uuid("177ce9c9328e856be8a4b87d40793e16"));
    signresponse1.setSignature(psbtSignatureData);
    signresponse1.setOrigin("NGRAVE");
    
    SignResponse signresponse2;
    psbtSignatureData = fromHex("");
    signresponse2.setRequestID(Uuid("91392cee288586fbce25e7ac3d56b580"));
    signresponse2.setSignature(psbtSignatureData);
    signresponse2.setOrigin("NGRAVE");
    
    batchSignResponse.setSignResponses({signresponse0, signresponse1, signresponse2});

    const auto expectedBytes = fromHex("");
    const auto expectedUR = "ur:batch-sign-";    

    // First sign-response is missing the requestId
    CPPUNIT_ASSERT_THROW(batchSignResponse.toCbor(), CborException);
    
    // First sign-response having the requestId as empty str
    signresponse0.setRequestID(Uuid(""));
    batchSignResponse.setSignResponses({signresponse0, signresponse1, signresponse2});
    CPPUNIT_ASSERT_THROW(batchSignResponse.toCbor(), CborException);
    
    // Valid batch-sign-response
    signresponse0.setRequestID(Uuid("3B5414375E3A450B8FE1251CBC2B3FB5"));
    batchSignResponse.setSignResponses({signresponse0, signresponse1, signresponse2});

    ValidateCborResults(batchSignResponse, expectedBytes);
    ValidateUrEncoding(batchSignResponse, expectedUR);
}

void TestUrSignatures::EncodeCosmosSignatureKeystoneTestcase()
{
    const std::string request_id = "9b1deb4d-3b7d-4bad-9bdd-2b0d7b3dcb6d";
    const auto cosmosSignatureData = fromHex("47e7b510784406dfa14d9fd13c3834128b49c56ddfc28edb02c5047219779adeed12017e2f9f116e83762e86f805c7311ea88fb403ff21900e069142b1fb310e");
    const auto expectedBytes = fromHex("a301d825509b1deb4d3b7d4bad9bdd2b0d7b3dcb6d02584047e7b510784406dfa14d9fd13c3834128b49c56ddfc28edb02c5047219779adeed12017e2f9f116e83762e86f805c7311ea88fb403ff21900e069142b1fb310e0358208e53e7b10656816de70824e3016fc1a277e77825e12825dc4f239f418ab2e04e");
    const auto pubKey = fromHex("8e53e7b10656816de70824e3016fc1a277e77825e12825dc4f239f418ab2e04e");
    const auto expectedUR = "ur:cosmos-signature/otadtpdagdndcawmgtfrkigrpmndutdnbtkgfssbjnaohdfzflvdrebeksfyamuroygtnettfneteebglugaskjnursamnuyaoskaajpcfktnyuewebgadkbdlnebyjtlskodmlnyaahstehckpdmyqzaxzmclmhbaammefwpazoehbaaxhdcxmnguvdpaamhflyjnvdaydkvladjlseoektvdksdavydedauogwcnnefpleprvtgloynbcfut";

    CosmosSignature cosmosSig(Uuid(request_id), cosmosSignatureData, pubKey);

    ValidateCborResults(cosmosSig, expectedBytes);
    ValidateUrEncoding(cosmosSig, expectedUR);
    
    // should fail if the pubkey is not set
    cosmosSig.setPublickey(std::nullopt);
    CPPUNIT_ASSERT_THROW(cosmosSig.toCbor(), CborException);
}
